// Scala la griglia (modifica il 5.0 per rimpicciolire/ingrandire)
vec3 p = pModel * 5.0; 

// Calcola lo spessore delle linee
vec3 grid = abs(fract(p - 0.5) - 0.5) / fwidth(p);
float line = min(min(grid.x, grid.y), grid.z);
float colorIntensity = 1.0 - min(line, 1.0);

// Colore di sfondo scuro, linee azzurre brillanti
textureCol = mix(vec3(0.05, 0.05, 0.1), vec3(0.2, 0.8, 1.0), colorIntensity);
